from collections import defaultdict

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight
from QuantConnect.Orders import OrderStatus
from QuantConnect.Symbol import Symbol


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self._bar_date = None
        self._bucket_end = None
        self._minute_bars = {}

        self._closes = []
        self._entry_order_id = None
        self._exit_order_id = None
        self._held_option = None
        self._entry_price = None
        self._no_entry_today = False
        self._equity_cleanup_submitted = False
        self._last_expiry_processing_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._bar_date != current_date:
            self._bar_date = current_date
            self._bucket_end = None
            self._minute_bars = {}
            self._no_entry_today = False
            self._equity_cleanup_submitted = False

        self._handle_unexpected_equity()
        self._process_expiration()
        self._process_time_stop(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        completed_bar = self._accept_minute_bar(bar)

        if completed_bar is None:
            return

        crossover = self._update_averages(completed_bar.Close)

        if not crossover:
            return

        bar_end = completed_bar.EndTime
        bar_time = bar_end.time()

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self._no_entry_today:
            return

        if self._entry_order_is_open():
            return

        if self._held_option_is_invested():
            return

        self._enter_from_current_chain(slice, completed_bar.Close)

    def _accept_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_time = end_time.time()

        if not (time(9, 30) < local_time <= time(16, 0)):
            return None

        anchor = datetime.combine(end_time.date(), time(9, 30))
        elapsed_minutes = int((end_time - anchor).total_seconds() // 60)

        if elapsed_minutes < 1 or elapsed_minutes > 390:
            return None

        bucket_index = (elapsed_minutes - 1) // 5
        bucket_end = anchor + timedelta(minutes=(bucket_index + 1) * 5)

        if self._bucket_end is not None and bucket_end != self._bucket_end:
            self._minute_bars = {}

        self._bucket_end = bucket_end
        self._minute_bars[end_time] = bar

        expected_times = [
            anchor + timedelta(minutes=bucket_index * 5 + offset)
            for offset in range(1, 6)
        ]

        if not all(expected in self._minute_bars for expected in expected_times):
            return None

        bars = [self._minute_bars[expected] for expected in expected_times]
        self._minute_bars = {}

        consolidated = TradeBar()
        consolidated.Symbol = self.spy
        consolidated.Time = bars[0].Time
        consolidated.EndTime = bucket_end
        consolidated.Open = bars[0].Open
        consolidated.High = max(x.High for x in bars)
        consolidated.Low = min(x.Low for x in bars)
        consolidated.Close = bars[-1].Close
        consolidated.Volume = sum(x.Volume for x in bars)

        return consolidated

    def _update_averages(self, close):
        if len(self._closes) < 20:
            self._closes.append(float(close))
            return False

        previous_fast = sum(self._closes[-5:]) / 5.0
        previous_slow = sum(self._closes[-20:]) / 20.0

        self._closes.append(float(close))
        if len(self._closes) > 20:
            self._closes.pop(0)

        current_fast = sum(self._closes[-5:]) / 5.0
        current_slow = sum(self._closes[-20:]) / 20.0

        return (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _enter_from_current_chain(self, slice: Slice, spy_price):
        chains = list(slice.OptionChains)

        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= float(spy_price) * 1.01
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        selected = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = selected[0]

        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket is None:
            self.Debug("Skipped entry: market order submission failed.")
            return

        self._entry_order_id = ticket.OrderId
        self.Debug("Entry submitted: " + str(contract.Symbol))

    def _process_time_stop(self, slice: Slice):
        if not self._held_option_is_invested():
            return

        if self._exit_order_is_open():
            return

        option_expiry = self._held_option.ID.Date.date()
        previous_trading_day = self._previous_trading_day(option_expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        quote = None
        if self._held_option in slice.QuoteBars:
            quote = slice.QuoteBars[self._held_option]

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0 or self._entry_price is None:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._cancel_open_exit()
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self._held_option is None:
            return

        expiry_date = self._held_option.ID.Date.date()

        if self.Time.date() >= expiry_date:
            if self._last_expiry_processing_date != self.Time.date():
                self._last_expiry_processing_date = self.Time.date()
                self._no_entry_today = True
                self.Debug("Expiration processing: liquidating held option.")

            if self._held_option_is_invested() and not self._exit_order_is_open():
                self._submit_exit("expiration protection")

    def _handle_unexpected_equity(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self._equity_cleanup_submitted = False
            return

        self._no_entry_today = True

        if not self._equity_cleanup_submitted:
            self._equity_cleanup_submitted = True
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.MarketOrder(self.spy, -quantity)

    def _submit_exit(self, reason):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity

        if quantity == 0 or self._exit_order_is_open():
            return

        ticket = self.MarketOrder(self._held_option, -quantity)

        if ticket is not None:
            self._exit_order_id = ticket.OrderId
            self.Debug("Exit submitted: " + reason)

    def _cancel_open_exit(self):
        if self._exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self._exit_order_id)

        if ticket is not None:
            status = ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled):
                ticket.Cancel("Replaced by profit-target exit")

        self._exit_order_id = None

    def _entry_order_is_open(self):
        if self._entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self._entry_order_id)

        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _exit_order_is_open(self):
        if self._exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self._exit_order_id)

        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _held_option_is_invested(self):
        return (
            self._held_option is not None
            and self.Portfolio[self._held_option].Invested
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order_id is not None
            and order_event.OrderId == self._entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_order_id = None
                self.Debug(
                    "Entry filled: "
                    + str(self._held_option)
                    + " at "
                    + str(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self._entry_order_id = None

        if (
            self._exit_order_id is not None
            and order_event.OrderId == self._exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self._exit_order_id = None
                self._held_option = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._exit_order_id = None

        try:
            if order_event.IsAssignment:
                self.Debug("Unexpected exercise or assignment order event.")
                self._no_entry_today = True
        except Exception:
            pass gale

