from AlgorithmImports import *
from collections import deque
from datetime import datetime, date, time, timedelta


class SpyBullishCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option_security.Symbol

        self.closes = deque(maxlen=20)
        self.bucket_date = None
        self.bucket_end = None
        self.bucket_closes = []
        self.bucket_valid = True
        self.bucket_last_minute = None

        self.current_spy_price = None

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_order_open = False
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_order_id = None
        self.exit_order_open = False

        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        if self.spy in slice.Bars:
            bar = slice.Bars[self.spy]
            self.current_spy_price = bar.Close
            self._process_minute_bar(bar.Close, now)

        self._handle_unexpected_spy_position()

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]

            if today >= self.entry_symbol.ID.Date.date():
                self.no_entry_date = today
                if holding.Quantity != 0:
                    self._submit_exit("expiration safeguard", force=True)

            elif holding.Quantity > 0:
                if self._is_pre_expiration_time_stop(today, now.time()):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._evaluate_profit_target(slice)

        if (
            self.bucket_end is not None
            and self.bucket_end.date() == today
            and self.bucket_end.time() >= time(9, 45)
            and self.bucket_end.time() <= time(14, 30)
        ):
            if self._has_open_holding() or self.entry_order_open:
                return

            if self.no_entry_date == today:
                return

            if self.current_spy_price is None or self.current_spy_price <= 0:
                self.Debug("Skipped entry: unavailable SPY price")
                return

            self._try_enter(slice)

    def _process_minute_bar(self, close, now):
        local_date = now.date()
        local_minute = now.hour * 60 + now.minute

        if local_minute < 9 * 60 + 31 or local_minute > 16 * 60:
            return

        minutes_from_session_start = local_minute - (9 * 60 + 30)
        bucket_end_minute = (
            9 * 60 + 30
            + (((minutes_from_session_start - 1) // 5) + 1) * 5
        )
        bucket_end = now.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_date != local_date or self.bucket_end != bucket_end:
            self._finalize_bucket()

            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_closes = []
            self.bucket_valid = True
