    def _process_minute_bar(self, bar, slice):
        end_time = bar.EndTime
        if end_time.date() != self.Time.date():
            return

        current_time = end_time.time()
        if current_time < datetime.strptime("09:31", "%H:%M").time():
            return
        if current_time > datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_end = self._get_bucket_end(end_time)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_minutes = {}

        self.bucket_minutes[end_time] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_minutes for t in expected_times):
            return

        bars = [self.bucket_minutes[t] for t in reversed(expected_times)]
        consolidated_close = bars[-1].Close

        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) == 5:
            previous_fast = sum(self.fast_closes) / 5.0
        if len(self.slow_closes) == 20:
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(consolidated_close)
        self.slow_closes.append(consolidated_close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_crossover:
            return

        close_time = bucket_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not (eligible_start <= close_time <= eligible_end):
