    def _get_bucket_end(self, end_time):
        session_start = end_time.replace(
            hour=9, minute=35, second=0, microsecond=0
        )

        if end_time <= session_start:
            return session_start

        elapsed_minutes = int((end_time - session_start).total_seconds() / 60)
        periods = (elapsed_minutes + 4) // 5

        return session_start + timedelta(minutes=periods * 5)

