        if quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment; liquidating.")
            self.MarketOrder(self.spy.Symbol, -quantity)
            self.blocked_date = self.Time.date()

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        status = self.entry_ticket.Status
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def GetPreviousTradingDay(self, expiry_date):
        expiry_datetime = datetime(
            expiry_date.year,
            expiry_date.month,
