        spy_price = None
        if slice.Bars.ContainsKey(self.spy_symbol):
            spy_price = float(slice.Bars[self.spy_symbol].Close)
        if spy_price is None or spy_price <= 0:
            spy_price = float(self.Securities[self.spy_symbol].Price)

        if spy_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        chains = list(slice.OptionChains.Values)

        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
