            self.Debug("Skipped entry: no qualifying strike at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {selected_expiry}, strike {selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled):
                return

        symbol = self.held_option.Symbol
        if not slice.QuoteBars.ContainsKey(symbol):
            return

        quote = slice.QuoteBars[symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("50% profit target")

    def EvaluateTimeStop(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if self.Time.date() != previous_trading_day:
            return

        if self.Time.hour > 15 or (
            self.Time.hour == 15 and self.Time.minute >= 45
        ):
            self.SubmitOptionExit("expiration time stop")

    def SubmitOptionExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled):
                if reason == "50% profit target":
                    self.exit_ticket.Cancel("Profit target superseded prior exit order")
                else:
                    return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol, -quantity
        )
        self.Debug(f"Exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)

                expiry_date = self.held_option.ID.Date.date()
                previous_trading_day = expiry_date - timedelta(days=1)
                exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

                while not exchange_hours.IsDateOpen(previous_trading_day):
                    previous_trading_day -= timedelta(days=1)

                self.time_stop_date = previous_trading_day
                self.Debug(
                    f"Entry filled: {order_event.Symbol.Value} "
                    f"at {self.entry_price:.4f}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol.Value}")
            self.held_option = None
            self.entry_price = None
            self.time_stop_date = None
            self.exit_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if "exercise" in message or "assignment" in message:
            self.Debug(
                "Unexpected option exercise or assignment event received; "
                "underlying position will be liquidated."
            )

