from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None
        self.expiration_processed = set()

    def OnData(self, slice: Slice):
        algorithm_date = self.Time.date()

        self._handle_unexpected_spy_position(algorithm_date)
        self._process_expiration(algorithm_date)
        self._evaluate_held_position(slice, algorithm_date)

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice, algorithm_date)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice, algorithm_date):
        bar_time = minute_bar.Time
        if bar_time.date() != algorithm_date:
            return

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute_of_day < session_start or minute_of_day >= session_end:
            return

        offset = minute_of_day - session_start
        bucket_minute = session_start + (offset // 5) * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.current_bucket is not None and bucket_start != self.current_bucket:
            self.bucket_bars = {}

        self.current_bucket = bucket_start
        self.bucket_bars[bar_time.minute] = minute_bar

        expected_minutes = {
            (bucket_minute + i) % 60 for i in range(5)
        }

        if bar_time.minute != (bucket_minute + 4) % 60:
            return

        actual_minutes = set(self.bucket_bars.keys())
        if not expected_minutes.issubset(actual_minutes):
            self.bucket_bars = {}
            return

        bars = [
            self.bucket_bars[
                datetime(
                    bar_time.year,
                    bar_time.month,
                    bar_time.day,
                    (bucket_minute + i) // 60,
                    (bucket_minute + i) % 60
                ).minute
            ]
            for i in range(5)
        ]

        close = bars[-1].Close
        completed_end = bucket_start + timedelta(minutes=5)

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        current_fast = None
        current_slow = None

        if len(self.fast_closes) == 5:
            current_fast = sum(self.fast_closes) / 5.0
        if len(self.slow_closes) == 20:
            current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = {}

        if not bullish_cross or self.no_entry_date == algorithm_date:
            return

        if not (time(9, 45) <= completed_end.time() <= time(14, 30)):
            return

        self._enter_from_chain(slice, close, algorithm_date)

    def _enter_from_chain(self, slice: Slice, spy_price: float, algorithm_date):
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        contracts = []
        for chain in slice.OptionChains:
            for contract in chain:
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
