        bar_time = minute_bar.Time
        if bar_time.date() != algorithm_date:
            return

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute_of_day < session_start or minute_of_day >= session_end:
            return

        offset = minute_of_day - session_start
        bucket_minute = session_start + (offset // 5) * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.current_bucket is not None and bucket_start != self.current_bucket:
            self.bucket_bars = {}

        self.current_bucket = bucket_start
        self.bucket_bars[bar_time.minute] = minute_bar

        expected_minutes = {
            (bucket_minute + i) % 60 for i in range(5)
        }

        if bar_time.minute != (bucket_minute + 4) % 60:
            return

