class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._manage_open_position(slice)

        if self.spy.Symbol in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy.Symbol], slice)

    def _process_minute_bar(self, bar, slice):
        bar_time = bar.Time.replace(second=0, microsecond=0)
        session_start = datetime.combine(bar_time.date(), time(9, 30))
        session_end = datetime.combine(bar_time.date(), time(16, 0))

        if bar_time < session_start or bar_time >= session_end:
            return

        elapsed_minutes = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._finalize_bucket(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(expected in self.bucket_bars for expected in expected_times):
            self._finalize_bucket(slice)
            self.bucket_start = None
            self.bucket_bars = {}

    def _finalize_bucket(self, slice):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(expected in self.bucket_bars for expected in expected_times):
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        consolidated = TradeBar(
            self.bucket_start,
            self.spy.Symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar, slice):
        current_fast = self.fast.Current.Value if self.fast.IsReady else None
        current_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if current_fast is not None and current_slow is not None:
            bullish_cross = (
                current_fast <= current_slow and
                self.fast.Current.Value > self.slow.Current.Value
            )

            bar_end_time = bar.EndTime.time()
            eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

            if bullish_cross and eligible_time:
                self._try_enter(slice)

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

    def _try_enter(self, slice):
        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible_contracts = []

        for contract in chain:
            expiry_date = contract.Expiry.date()

            if expiry_date < algorithm_date + timedelta(days=7):
                continue

            if contract.Right != OptionRight.Call:
                continue

            eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no eligible expiration or call.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        strike_floor = 1.01 * spy_price
        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _manage_open_position(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.UpdateSubmitted
            ):
                return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: " +
                    str(self.held_symbol) +
                    " at " +
                    str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                if (
                    self.held_symbol is None or
                    self.Portfolio[self.held_symbol].Quantity <= 0
                ):
                    self.Debug("Exit filled: " + str(order_event.Symbol))
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment position; liquidating."
            )
            self.MarketOrder(self.spy.Symbol, -quantity)

