    def OnData(self, slice):
        current_date = self.Time.date()

        # Ensure unexpected equity created by exercise or assignment is liquidated.
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

        # Expiration processing takes precedence over any new entry.
        if self.held_option is not None:
            if current_date >= self.entry_expiration:
                self.blocked_entry_date = current_date
                self._submit_exit("Expiration processing")
            else:
                self._evaluate_exit(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        spy_bar = slice.Bars[self.spy]
        self.latest_spy_price = spy_bar.Close
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar, slice):
        bar_time = bar.Time.replace(second=0, microsecond=0)
        bar_clock = bar_time.time()

        if bar_clock < time(9, 30) or bar_clock >= time(16, 0):
            return

        bucket_minute = 30 + ((bar_time.minute - 30) // 5) * 5
        bucket_start = bar_time.replace(minute=bucket_minute, second=0, microsecond=0)

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._finalize_bucket(slice)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _finalize_bucket(self, slice):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
            self.bucket_start = None
            self.bucket_bars = {}
            return

        close = self.bucket_bars[expected_times[-1]].Close
        end_time = self.bucket_start + timedelta(minutes=5)

        self._on_five_minute_close(close, end_time, slice)

        self.bucket_start = None
        self.bucket_bars = {}

    def _on_five_minute_close(self, close, end_time, slice):
        self.closes.append(float(close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        current_fast = None
        current_slow = None

        if len(self.closes) >= self.fast_period:
            current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period

        if len(self.closes) >= self.slow_period:
            current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            current_fast is not None and
            current_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None or self._order_is_open(self.entry_ticket):
            return

        self._enter_from_chain(slice)

    def _enter_from_chain(self, slice):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiration = expirations[0]
        minimum_strike = float(self.latest_spy_price) * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute crossover"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_exit(self, slice):
        if self.held_option is None:
            return

        held = self.Portfolio[self.held_option]
        if not held.Invested:
            return

        current_date = self.Time.date()
        previous_trading_day = self._previous_trading_day(self.entry_expiration)

        # The time stop applies even when no option quote is available.
        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        if not slice.QuoteBars.ContainsKey(self.held_option):
            return

        quote = slice.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            if self._order_is_open(self.exit_ticket):
                self.exit_ticket.Cancel("Profit target superseded")
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self._order_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_expiration = self.Securities[
                    self.held_option
                ].Symbol.ID.Date.date()
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.entry_expiration = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment handled.")
            if self.Portfolio[self.spy].Invested:
                self.Liquidate(self.spy, "Exercise or assignment liquidation")

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

