        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.EndTime.time().second != 0:
            return

        if bar.EndTime.minute % 5 != 0:
            return

        if bar.EndTime - bar.Time != timedelta(minutes=5):
            return

        if not self._is_regular_session_bar(bar):
            return

        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        if crossover:
            end_time = bar.EndTime.time()
            if (
                datetime.strptime("09:45", "%H:%M").time()
                <= end_time
                <= datetime.strptime("14:30", "%H:%M").time()
            ):
                self.pending_signal = (bar.EndTime, float(bar.Close))

