                self._try_enter(slice, spy_price)

    def _try_enter(self, slice, spy_price):
        today = self.Time.date()

        if self.entry_block_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry and contract.Right == OptionRight.Call:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        target_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no eligible call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _manage_open_option(self, slice):
        if self.held_option is None:
            return

        today = self.Time.date()

        if today >= self.held_expiry.date():
            self.entry_block_date = today
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(self.held_expiry.date())

        if (
            today == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self.entry_price is None:
            return

        quote = self._held_quote(slice)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            if reason == "profit target":
                self.exit_ticket.Cancel("Replaced by profit-target exit")
            else:
                return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Exit submitted: " + reason)

    def _held_quote(self, slice):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                try:
                    return float(contract.BidPrice), float(contract.AskPrice)
                except (TypeError, ValueError):
                    return None
        return None

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.held_expiry = self.Securities[self.held_option].Symbol.ID.Date
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(self.held_option))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None
            self.held_expiry = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        message = str(getattr(order_event, "Message", "")).lower()
        if is_assignment or "assignment" in message or "exercise" in message:
            self.entry_block_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment handling.")
            self._liquidate_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.entry_block_date = self.Time.date()
            self._liquidate_equity_position()

    def _liquidate_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        today = self.Time.date()

        if quantity != 0 and self.equity_liquidation_date != today:
            self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_date = today
            self.Debug("Unexpected SPY equity position liquidated.")

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_regular_session_bar(self, bar):
        start = bar.Time.time()
        end = bar.EndTime.time()
        return (
            start >= datetime.strptime("09:30", "%H:%M").time()
            and end <= datetime.strptime("16:00", "%H:%M").time()
        )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

