from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_start = None
        self.minute_bucket_closes = []

        self.entry_ticket = None
        self.entry_order_id = None
        self.exit_ticket = None
        self.exit_order_id = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None

        self.no_entry_date = None
        self.last_equity_liquidation_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never treat an unexpected SPY position as a strategy position.
        if self.Portfolio[self.spy].Invested:
            self.no_entry_date = today
            if self.last_equity_liquidation_date != today:
                quantity = self.Portfolio[self.spy].Quantity
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self.MarketOrder(self.spy, -quantity, "Unexpected exercise/assignment")
                self.last_equity_liquidation_date = today

        self._refresh_order_state()

        # Expiration protection and the preceding-day time stop.
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            if self.held_expiry is not None:
                expiry_date = self.held_expiry.date()

                if today >= expiry_date:
                    self.no_entry_date = today
                    self.Debug("Expiration processing began; liquidating option.")
                    self._submit_exit("Expiration protection")
                elif (
                    today == expiry_date - timedelta(days=1)
                    and self.Time.time() >= time(15, 45)
                ):
                    self.no_entry_date = today
                    self._submit_exit("Pre-expiration time stop")

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_start = bar.Time.replace(second=0, microsecond=0)

        if minute_start.time() < time(9, 30) or minute_start.time() >= time(16, 0):
            return

        bucket_start = minute_start.replace(
            minute=(minute_start.minute // 5) * 5
        )

        if self.minute_bucket_start != bucket_start:
            self.minute_bucket_start = bucket_start
            self.minute_bucket_closes = []

        expected_minute = bucket_start + timedelta(
            minutes=len(self.minute_bucket_closes)
        )

        if minute_start != expected_minute:
            # A missing or out-of-order minute invalidates this five-minute bar.
            self.minute_bucket_closes = []
            if minute_start != bucket_start:
                self.minute_bucket_start = None
            return

        self.minute_bucket_closes.append(float(bar.Close))

        if len(self.minute_bucket_closes) != 5:
            return

        consolidated_close = self.minute_bucket_closes[-1]
        consolidated_end = bucket_start + timedelta(minutes=5)
        self.minute_bucket_closes = []

        self.closes.append(consolidated_close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            bullish_crossover
            and time(9, 45) <= consolidated_end.time() <= time(14, 30)
        ):
            self._evaluate_entry(slice, consolidated_close)

    def _evaluate_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.entry_order_id is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.exit_order_id is not None:
            return

        chain = None
        try:
