from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option = option

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_ticket = None
        self.entry_order_id = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            local_time = end_time.astimezone().replace(tzinfo=None)
        else:
            local_time = end_time

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish:
            return

        bar_time = local_time.time()
        if not (datetime.strptime("09:45", "%H:%M").time()
                <= bar_time
                <= datetime.strptime("14:30", "%H:%M").time()):
            return

        self.TryEnter(self.CurrentSlice)

    def TryEnter(self, slice):
        current_date = self.Time.date()

        if self.expiration_block_date == current_date:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                          OrderStatus.PartiallyFilled):
                return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        chains = self.GetChains(slice)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                contracts.append(contract)

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expiries[0]
        threshold = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol.Value))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_block_date = current_date
                self.SubmitExit("expiration processing")
            else:
                previous_trading_day = self.PreviousTradingDay(expiry_date)
                if (current_date == previous_trading_day
                        and self.Time.time() >= datetime.strptime(
                            "15:45", "%H:%M").time()):
                    self.SubmitExit("expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

    def CheckProfitTarget(self, slice):
        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New, OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                return

        if self.entry_price is None or self.held_symbol is None:
            return

        contract = self.FindContract(slice, self.held_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New, OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                if reason == "50% profit target":
                    self.Transactions.CancelOrder(self.exit_ticket.OrderId)
                else:
                    return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled.")
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment received.")

    def GetChains(self, slice):
        if slice is None or not slice.OptionChains:
            return []

        try:
            return list(slice.OptionChains.Values)
        except AttributeError:
            return list(slice.OptionChains)

    def FindContract(self, slice, symbol):
        for chain in self.GetChains(slice):
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def PreviousTradingDay(self, date_value):
        hours = self.Securities[self.spy].Exchange.Hours
        candidate = datetime(date_value.year, date_value.month, date_value.day) - timedelta(days=1)

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

