                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled.")
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment received.")

    def GetChains(self, slice):
        if slice is None or not slice.OptionChains:
            return []

        try:
            return list(slice.OptionChains.Values)
        except AttributeError:
            return list(slice.OptionChains)

    def FindContract(self, slice, symbol):
        for chain in self.GetChains(slice):
            if symbol in chain.Contracts:
