        end_time = bar.EndTime

        if not self._is_regular_session_time(end_time):
            return

        minute_end = end_time.replace(second=0, microsecond=0)

        if self.previous_minute_end is not None:
            if minute_end <= self.previous_minute_end:
                return

        self.previous_minute_end = minute_end

        minute_base = minute_end.replace(second=0, microsecond=0)
        remainder = minute_base.minute % 5
        if remainder == 0:
            new_bucket_end = minute_base
        else:
            new_bucket_end = minute_base + timedelta(minutes=5 - remainder)

        if self.bucket_end is None:
            self.bucket_end = new_bucket_end
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_close = None

        elif new_bucket_end != self.bucket_end:
            self.bucket_end = new_bucket_end
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_close = None

        if self.bucket_count > 0:
            expected = minute_end - timedelta(minutes=1)
            if expected != self.previous_bucket_minute_end:
                self.bucket_valid = False

        self.bucket_count += 1
        self.bucket_close = bar.Close
        self.previous_bucket_minute_end = minute_end

        if minute_end != self.bucket_end:
            return

        if self.bucket_count == 5 and self.bucket_valid:
            consolidated = TradeBar(
                self.bucket_end - timedelta(minutes=5),
                self.spy,
                bar.Open,
                bar.High,
                bar.Low,
                bar.Close,
                bar.Volume,
                timedelta(minutes=5)
            )
            self._process_five_minute_bar(consolidated)

        self.bucket_end = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_close = None
        self.previous_bucket_minute_end = None

    def _process_five_minute_bar(self, bar: TradeBar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime
        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._evaluate_entry()

    def _evaluate_entry(self):
        current_date = self.Time.date()

        if self.blocked_date == current_date:
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        slice = self.CurrentSlice
        if slice is None or not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped call selection: no current SPY price.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidate_chains = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidate_chains.append(contract)

        if not candidate_chains:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidate_chains)

        contracts = [
            contract for contract in candidate_chains
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            contracts,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY call entry"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_is_open():
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = float(quote.Bid)
        ask = float(quote.Ask)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Entered 1 call: {0} at {1:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited call: {0} at {1:.4f}".format(
                        order_event.Symbol, float(order_event.FillPrice)
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        order_type = getattr(order_event, "OrderType", None)
        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        if is_assignment or order_type == OrderType.OptionExercise:
            self.blocked_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment handled.")
            self._handle_unexpected_spy_position(self.Time.date())

    def _handle_unexpected_spy_position(self, current_date):
        quantity = int(self.Portfolio[self.spy].Quantity)
        if quantity == 0:
            return

        self.blocked_date = current_date

        if self.equity_liquidation_ticket is not None:
            status = self.equity_liquidation_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ):
                return

        self.Debug("Unexpected SPY equity position; liquidating immediately.")
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _is_immediately_preceding_trading_day(self, expiry_date):
        try:
            expiry_datetime = datetime(
                expiry_date.year, expiry_date.month, expiry_date.day
            )
            previous = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
                expiry_datetime
            )
            previous_date = previous.date() if hasattr(previous, "date") else previous
            return self.Time.date() == previous_date
        except Exception:
            previous_date = expiry_date - timedelta(days=1)
            while previous_date.weekday() >= 5:
                previous_date -= timedelta(days=1)
            return self.Time.date() == previous_date

    def _is_regular_session_time(self, time):
        session_start = (9, 30)
        session_end = (16, 0)
        current = (time.hour, time.minute)
        return session_start < current <= session_end

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

