        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._evaluate_expiration_stop()
            self._evaluate_time_stop()
            self._evaluate_profit_target(data)

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            return

        if self.no_entry_date == self.Time.date():
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        local_time = bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        tod = local_time.time()
        if tod < datetime.time(9, 31) or tod > datetime.time(16, 0):
            return

        minute = local_time.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_hour = local_time.hour + bucket_end_minute // 60
        bucket_end_minute %= 60

        bucket_end = local_time.replace(
            hour=bucket_hour,
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )
        bucket_key = (local_time.date(), bucket_end)

        if self.current_bucket != bucket_key:
            self._complete_previous_bucket(data)
            self.current_bucket = bucket_key
            self.bucket_bars = {}

        self.bucket_bars[local_time] = bar

        if local_time == bucket_end:
            self._complete_previous_bucket(data)
            self.current_bucket = None
            self.bucket_bars = {}

    def _complete_previous_bucket(self, data: Slice):
        if not self.bucket_bars or self.current_bucket is None:
            return

        expected = set()
        bucket_end = self.current_bucket[1]
        for offset in range(1, 6):
            expected.add(bucket_end - timedelta(minutes=offset))

        if set(self.bucket_bars.keys()) != expected:
            return

        bars = [self.bucket_bars[t] for t in sorted(self.bucket_bars)]
        close = bars[-1].Close
        bar_end = bucket_end

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 5:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
        if len(self.closes) >= 20:
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish:
            return

        if not (
            datetime.time(9, 45) <= bar_end.time() <= datetime.time(14, 30)
        ):
            return

        self._try_enter(data, close)

