from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.minute_bucket_end = None
        self.minute_bars = []

        self.pending_entry = False
        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_liquidation_open = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            if not self.equity_liquidation_open:
                quantity = -self.Portfolio[self.spy].Quantity
                self.Debug("Unexpected SPY equity position; liquidating immediately.")
                self.MarketOrder(self.spy, quantity, tag="Unexpected exercise/assignment")
                self.equity_liquidation_open = True
            return

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self._submit_exit("Expiration protection")
            elif self._is_pre_expiration_trading_day(today, expiry_date):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self._submit_exit("Pre-expiration time stop")
            else:
                self._check_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._accept_minute_bar(spy_bar)

        if not self.pending_entry:
            return

        self.pending_entry = False

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        self._select_and_enter(slice, spy_bar.Close)

    def _accept_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        total_minutes = end_time.hour * 60 + end_time.minute

        if total_minutes <= 30 or total_minutes > 960:
            return

        bucket_end_minute = ((total_minutes - 30) // 5) * 5 + 35
        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.minute_bucket_end is not None and bucket_end != self.minute_bucket_end:
            self._finish_minute_bucket()

        if self.minute_bucket_end is None:
            self.minute_bucket_end = bucket_end

        self.minute_bars.append(bar)

        if end_time == bucket_end:
            self._finish_minute_bucket()

    def _finish_minute_bucket(self):
        if self.minute_bucket_end is None:
            return

        bars = self.minute_bars
        bucket_end = self.minute_bucket_end

        self.minute_bars = []
        self.minute_bucket_end = None

        if len(bars) != 5:
            return

        expected = [
            bucket_end - timedelta(minutes=4),
            bucket_end - timedelta(minutes=3),
            bucket_end - timedelta(minutes=2),
            bucket_end - timedelta(minutes=1),
            bucket_end
        ]

        actual = [bar.EndTime for bar in bars]
        if actual != expected:
            return

        consolidated_close = bars[-1].Close
        previous_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        previous_slow = float(self.slow.Current.Value) if self.slow.IsReady else None

        self.fast.Update(bucket_end, consolidated_close)
        self.slow.Update(bucket_end, consolidated_close)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bucket_end.time()
        if bullish_cross and (
            timedelta(hours=9, minutes=45) <=
            timedelta(
                hours=bar_time.hour,
                minutes=bar_time.minute
            ) <=
            timedelta(hours=14, minutes=30)
        ):
            self.pending_entry = True

    def _select_and_enter(self, slice: Slice, spy_price):
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        earliest_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= earliest_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying option expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        minimum_strike = 1.01 * float(spy_price)

        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self._order_closed(self.exit_ticket):
            return

        contract = None
        for chain in slice.OptionChains.Values:
            if self.held_symbol in chain.Contracts:
                contract = chain.Contracts[self.held_symbol]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._order_closed(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None and
            not self._order_closed(self.entry_ticket)
        )

    def _order_closed(self, ticket):
        return ticket is None or ticket.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.MarginClosed
        ]

    def _is_pre_expiration_trading_day(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ]:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ]:
                self.Debug(
                    "Exit filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                self.exit_ticket = None

        if order_event.Symbol == self.spy and order_event.Status == OrderStatus.Filled:
            self.equity_liquidation_open = False
            if order_event.Quantity != 0:
                self.Debug("Unexpected exercise or assignment handling completed.")

    def OnAssignmentOrderEvent(self, assignment_event):
        if self.Portfolio[self.spy].Quantity != 0 and not self.equity_liquidation_open:
            quantity = -self.Portfolio[self.spy].Quantity
            self.Debug("Unexpected assignment received; liquidating SPY.")
            self.MarketOrder(self.spy, quantity, tag="Unexpected assignment")
            self.equity_liquidation_open = True

