        end_time = bar.EndTime
        total_minutes = end_time.hour * 60 + end_time.minute

        if total_minutes <= 30 or total_minutes > 960:
            return

        bucket_end_minute = ((total_minutes - 30) // 5) * 5 + 35
        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.minute_bucket_end is not None and bucket_end != self.minute_bucket_end:
            self._finish_minute_bucket()

        if self.minute_bucket_end is None:
            self.minute_bucket_end = bucket_end

        self.minute_bars.append(bar)

        if end_time == bucket_end:
            self._finish_minute_bucket()

    def _finish_minute_bucket(self):
        if self.minute_bucket_end is None:
            return

        bars = self.minute_bars
        bucket_end = self.minute_bucket_end

        self.minute_bars = []
        self.minute_bucket_end = None

        if len(bars) != 5:
            return

        expected = [
            bucket_end - timedelta(minutes=4),
            bucket_end - timedelta(minutes=3),
            bucket_end - timedelta(minutes=2),
            bucket_end - timedelta(minutes=1),
            bucket_end
        ]

        actual = [bar.EndTime for bar in bars]
        if actual != expected:
            return

        consolidated_close = bars[-1].Close
        previous_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        previous_slow = float(self.slow.Current.Value) if self.slow.IsReady else None

        self.fast.Update(bucket_end, consolidated_close)
        self.slow.Update(bucket_end, consolidated_close)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bucket_end.time()
        if bullish_cross and (
            timedelta(hours=9, minutes=45) <=
            timedelta(
                hours=bar_time.hour,
                minutes=bar_time.minute
            ) <=
            timedelta(hours=14, minutes=30)
        ):
            self.pending_entry = True

    def _select_and_enter(self, slice: Slice, spy_price):
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        earliest_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= earliest_expiry:
                    candidates.append(contract)

