            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute).Symbol
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0

        self.minute_bucket = None
        self.minute_bars = {}

        self.current_slice = None
        self.current_spy_price = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.expiration_block_date = None
        self.equity_cleanup_submitted = False

    def OnData(self, slice: Slice):
        self.current_slice = slice

        if self.expiration_block_date != self.Time.date():
            self.expiration_block_date = None

        self._process_expiration()
        self._handle_unexpected_equity_position()
        self._evaluate_option_exit()

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self.current_spy_price = bar.Close
            self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        local_time = bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.time() < time(9, 31) or local_time.time() > time(16, 0):
            return

        bucket_end = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if local_time.minute % 5 != 0:
            bucket_end += timedelta(minutes=5)

        if self.minute_bucket is not None and bucket_end != self.minute_bucket:
            self.minute_bars = {}

        self.minute_bucket = bucket_end
        self.minute_bars[local_time] = bar

        if local_time.minute % 5 != 0:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if not all(t in self.minute_bars for t in expected_times):
            self.minute_bars = {}
            return

        bars = [self.minute_bars[t] for t in expected_times]
        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )
        consolidated.EndTime = bucket_end

        self.minute_bars = {}
        self._on_five_minute_bar(consolidated)

    def _on_five_minute_bar(self, bar: TradeBar):
        previous_fast = None
        previous_slow = None

        if len(self.fast_values) == 5:
            previous_fast = self.fast_sum / 5.0
        if len(self.slow_values) == 20:
            previous_slow = self.slow_sum / 20.0

        self.fast_values.append(bar.Close)
        self.fast_sum += bar.Close
        if len(self.fast_values) == 5:
            self.fast_sum -= sum([]) if False else 0.0

        self.slow_values.append(bar.Close)
        self.slow_sum += bar.Close

        while len(self.fast_values) > 5:
            self.fast_sum -= self.fast_values.popleft()
        while len(self.slow_values) > 20:
            self.slow_sum -= self.slow_values.popleft()

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = self.fast_sum / 5.0
        current_slow = self.slow_sum / 20.0

        bar_time = bar.EndTime
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        eligible_time = time(9, 45) <= bar_time.time() <= time(14, 30)
        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._try_enter_call()

    def _try_enter_call(self):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self._entry_order_is_open():
            return

        if self.current_spy_price is None:
            self.Debug("Skipped selection: SPY price unavailable.")
            return

        chains = self.current_slice.OptionChains
        chain = chains.get(self.spy_option)
        if chain is None:
            self.Debug("Skipped selection: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * self.current_spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_option_exit(self):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0 or self._entry_order_is_open():
            return

        if self._exit_order_is_open():
            return

        quote = self.current_slice.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_symbol].Quantity > 0:
                self._submit_exit("expiration protection")

            self.Debug("Expiration processing began; entry blocked for today.")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replaced by higher-priority liquidation")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _handle_unexpected_equity_position(self):
        equity_quantity = self.Portfolio[self.spy].Quantity

        if equity_quantity != 0 and not self.equity_cleanup_submitted:
            self.Debug("Unexpected exercise or assignment created SPY equity; liquidating.")
            self.Liquidate(self.spy, tag="Unexpected exercise or assignment")
            self.equity_cleanup_submitted = True
            self.expiration_block_date = self.Time.date()
        elif equity_quantity == 0:
            self.equity_cleanup_submitted = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: " +
                    str(self.held_symbol) +
                    " at " +
                    str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: " + str(self.held_symbol))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment event received.")
            self.expiration_block_date = self.Time.date()

        if order_event.Symbol.SecurityType == SecurityType.Equity:
            if order_event.Symbol == self.spy and getattr(order_event, "IsAssignment", False):
                self.Debug("Assignment event affected SPY equity; cleanup submitted.")
                self.Liquidate(self.spy, tag="Assignment cleanup")
                self.expiration_block_date = self.Time.date()

