        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replaced by higher-priority liquidation")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

