            self.expiration_block_date = self.Time.date()

        if order_event.Symbol.SecurityType == SecurityType.Equity:
            if order_event.Symbol == self.spy and getattr(order_event, "IsAssignment", False):
                self.Debug("Assignment event affected SPY equity; cleanup submitted.")
                self.Liquidate(self.spy, tag="Assignment cleanup")
