        session_end = local_time.replace(hour=16, minute=0)

        if local_time < session_start or local_time >= session_end:
            return

        minutes_from_open = int((local_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_start is None:
            self.bucket_date = current_date
            self.bucket_start = bucket_start
        elif current_date != self.bucket_date or bucket_start != self.bucket_start:
            self._complete_bucket(slice)

            self.bucket_date = current_date
            self.bucket_start = bucket_start
