            self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar, slice):
        end = minute_bar.EndTime
        date = end.date()

        if self.bucket_date != date:
            self.bucket_date = date
            self.bucket_bars = []
            self.bucket_next_end = None

        if end.hour != 9 and not self.bucket_bars:
            if end.hour < 9:
                return

        if not self.bucket_bars:
            if not self._is_bucket_start(end):
                return

            self.bucket_bars = [minute_bar]
            self.bucket_next_end = end + timedelta(minutes=1)
            return

        if end != self.bucket_next_end:
            self.bucket_bars = []
            self.bucket_next_end = None

            if self._is_bucket_start(end):
                self.bucket_bars = [minute_bar]
                self.bucket_next_end = end + timedelta(minutes=1)
            return

        self.bucket_bars.append(minute_bar)
        self.bucket_next_end = end + timedelta(minutes=1)

        if len(self.bucket_bars) != 5:
            return

        consolidated_end = end
        close = minute_bar.Close

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(IndicatorDataPoint(self.spy, consolidated_end, close))
        self.slow.Update(IndicatorDataPoint(self.spy, consolidated_end, close))

        bullish_cross = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.bucket_bars = []
        self.bucket_next_end = None

        if not bullish_cross:
            return

        if not self._is_eligible_entry_time(consolidated_end):
            return

        self._try_enter(slice, close, consolidated_end.date())

    def _is_bucket_start(self, end):
        if end.hour != 9 and end.hour != 10 and end.hour != 11 and end.hour != 12 and end.hour != 13 and end.hour != 14 and end.hour != 15:
            return False

        if end.hour == 9 and end.minute == 31:
            return True

        return end.minute % 5 == 1

    def _is_eligible_entry_time(self, end):
        minutes = end.hour * 60 + end.minute
        return 9 * 60 + 45 <= minutes <= 14 * 60 + 30

    def _try_enter(self, slice, spy_price, algorithm_date):
        if self.blocked_entry_date == algorithm_date:
            return

        if self.entry_ticket is not None or self.entry_order_id is not None:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = []
        for chain in slice.OptionChains.Values:
            chains.append(chain)

        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        expirations = []

        for chain in chains:
            for contract in chain:
                symbol = contract.Symbol
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue
                expiry = symbol.ID.Date.date()
                if expiry >= minimum_expiry:
                    expirations.append(expiry)

        if not expirations:
            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        selected_expiry = min(expirations)
        minimum_strike = spy_price * 1.01
        candidates = []

        for chain in chains:
            for contract in chain:
                symbol = contract.Symbol
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue
                if symbol.ID.Date.date() != selected_expiry:
                    continue
                if symbol.ID.Strike < minimum_strike:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(
            key=lambda contract: (
                contract.Symbol.ID.Strike,
                str(contract.Symbol)
            )
        )
        selected = candidates[0]
        selected_symbol = selected.Symbol

        self.entry_symbol = selected_symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = (
            self.entry_ticket.OrderId if self.entry_ticket is not None else None
        )

    def _process_option_exit(self, slice, now):
        symbol = self.entry_symbol

        if symbol is None:
            return

        if not self.Portfolio[symbol].Invested:
            return

        expiry = symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if now.date() == previous_trading_day and (
            now.hour > 15 or (now.hour == 15 and now.minute >= 45)
        ):
            self._submit_exit(symbol, "Expiration-eve time stop")
            return

        if self.exit_ticket is not None:
            return

        quote = self._get_current_quote(slice, symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit(symbol, "50 percent profit target")

    def _process_expiration(self, now, today):
        if self.entry_symbol is None:
            return

        expiry = self.entry_symbol.ID.Date.date()
        if today < expiry:
            return

        self.blocked_entry_date = today

        if self.Portfolio[self.entry_symbol].Invested:
            self._submit_exit(self.entry_symbol, "Expiration safeguard")

    def _submit_exit(self, symbol, reason):
        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        quantity = self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _get_current_quote(self, slice, symbol):
        if not slice.QuoteBars.ContainsKey(symbol):
            return None

        quote_bar = slice.QuoteBars[symbol]
        if quote_bar.Bid is None or quote_bar.Ask is None:
            return None

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close
        return bid, ask

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self, today):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if self.exercise_handled_date == today:
            return

        self.exercise_handled_date = today
        self.Debug("Unexpected exercise or assignment created SPY equity; liquidating.")
        self.MarketOrder(self.spy, -holding.Quantity, tag="Unexpected exercise safeguard")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: " + str(self.entry_symbol) +
                    " at " + str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and order_event.Status != OrderStatus.PartiallyFilled:
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: " + str(self.entry_symbol))
                    self.exit_ticket = None
                    self.entry_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

