from AlgorithmImports import *
from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.minute_buckets = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._process_option_exit(slice)

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.CancelPending,
                OrderStatus.Filled,
            ):
                if status != OrderStatus.Filled:
                    self.entry_ticket = None

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        if end.hour < 9 or end.hour > 16:
            return
        if end.hour == 9 and end.minute < 31:
            return
        if end.hour == 16 and end.minute > 0:
            return

        minute = end.hour * 60 + end.minute
        if minute < 9 * 60 + 31:
            return

        slot = (minute - (9 * 60 + 31)) // 5
        bucket_end_minutes = 9 * 60 + 35 + slot * 5
        bucket_end = datetime(
            end.year,
            end.month,
            end.day,
            bucket_end_minutes // 60,
            bucket_end_minutes % 60,
        )

        key = (end.date(), bucket_end)
        bucket = self.minute_buckets.setdefault(key, {})
        bucket[end.minute + end.hour * 60] = bar

        if minute != bucket_end_minutes:
            return

        expected_minutes = {
            bucket_end_minutes - 4,
            bucket_end_minutes - 3,
            bucket_end_minutes - 2,
            bucket_end_minutes - 1,
            bucket_end_minutes,
        }

        if not expected_minutes.issubset(bucket.keys()):
            self.minute_buckets.pop(key, None)
            return

        bars = [bucket[m] for m in sorted(expected_minutes)]
        consolidated = TradeBar(
            bucket_end,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5),
        )
        self.minute_buckets.pop(key, None)
        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return
        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        local_time = bar.EndTime.time()
        if not bullish_cross:
            return
        if not (time(9, 45) <= local_time <= time(14, 30)):
            return
        if self.no_entry_date == self.Time.date():
            return
        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        self._select_and_enter(slice, bar.Close)

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover call entry"
        )
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return
        if self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (x for x in chain if x.Symbol == self.held_symbol),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration protection")
            return

        preceding_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            preceding_trading_day
        ):
            preceding_trading_day -= timedelta(days=1)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        if self.entry_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_symbol, reason)
        )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug(
            "Unexpected exercise or assignment: liquidating SPY equity position."
        )
        self.Liquidate(self.spy, tag="Unexpected option exercise or assignment")
        self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.entry_ticket = None
                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_symbol, self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0} at {1}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assign" in message or "assignment" in message:
            self.Debug(
                "Unexpected exercise or assignment event received."
            )
            self._handle_unexpected_equity_position()

