        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            bullish_cross
            and eligible_start <= close_time <= eligible_end
            and self._blocked_entry_date != last.EndTime.date()
        ):
            self._try_enter(slice, close_price, last.EndTime.date())

    def _try_enter(self, slice: Slice, spy_price: float, algorithm_date):
        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return
        if self._entry_ticket is not None and self._entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        contracts = list(chain.Contracts.Values)
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if (contract.Expiry.date() - algorithm_date).days >= 7
            }
        )

        if not expirations:
            self.Debug("Entry skipped: no expiration at least 7 days out")
            return

        expiration = expirations[0]
        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY crossover entry",
        )
        self._entry_price = None
        self._held_symbol = selected.Symbol
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_exit(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return
        if self._exit_ticket is not None and self._exit_ticket.Status not in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Filled,
        ):
            return

        bid, ask = self._current_option_quote(slice, self._held_symbol)
        if bid is not None and ask is not None and bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self._entry_price:
                self._submit_exit("50% profit target")
                return

        expiration = self._held_symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiration)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        if self._exit_ticket is not None and self._exit_ticket.Status not in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Filled,
        ):
            self._exit_ticket.Cancel("Replaced by {}".format(reason))

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -holding.Quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _process_expiration_date(self):
        if self._held_symbol is None:
            return

        expiration = self._held_symbol.ID.Date.date()
        if self.Time.date() == expiration:
            self._blocked_entry_date = self.Time.date()
            if self.Portfolio[self._held_symbol].Invested:
                self._submit_exit("expiration protection")

    def _current_option_quote(self, slice: Slice, symbol):
        quote = slice.QuoteBars.get(symbol)
        if quote is not None:
            bid = quote.Bid.Close if quote.Bid is not None else None
            ask = quote.Ask.Close if quote.Ask is not None else None
            return bid, ask

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract.BidPrice, contract.AskPrice

        return None, None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if self._equity_liquidation_ticket is None:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
            self._equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment",
            )

